#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n, a, b, c;
    cin >> n >> a >> b >> c;

    long long ans = 0;

    for (long long i = 0; i <= a && i <= n; ++i) {
        if ((n - i) % 2 != 0) continue;

        long long j = (n - i) / 2;
        if (j > b) continue;

        long long u = b - j;
        long long lower = max(0LL, i - c);
        long long upper = min(i, u / 2);

        if (lower <= upper) ans += upper - lower + 1;
    }

    cout << ans << '\n';
    return 0;
}

